<?php
 namespace Pterodactyl\Console\Commands\Dezerx; use Illuminate\Console\Command; use Pterodactyl\Services\Dezerx\Addons; use Pterodactyl\Services\Dezerx\Overview\Collector; class CollectOverview extends Command { protected $signature = 'dezerx:overview-collect'; protected $description = 'Record every node\'s server usage for the admin overview.'; public function handle(Collector $collector): int { if (!(Addons::get(Addons::ADMIN_OVERVIEW)['enabled'] ?? false)) { return 0; } $summary = $collector->run(); $this->line(sprintf('%d of %d nodes answered, %d servers, %d ms.', $summary['reachable'], $summary['nodes'], $summary['servers'], $summary['ms'])); return 0; } } 